def regex_search(pattern: str, text: str) -> bool:
    DOT = -1
    C_NONE = 0
    C_START = 1
    C_END = 2

    p = pattern
    pn = len(p)
    tn = len(text)
    text_codes = [ord(c) for c in text]

    eps_edges: list[list[tuple[int, int]]] = []
    char_edges: list[list[tuple[object, int]]] = []

    def new_state() -> int:
        idx = len(eps_edges)
        eps_edges.append([])
        char_edges.append([])
        return idx

    def add_eps(s: int, t: int, cond: int = C_NONE) -> None:
        eps_edges[s].append((t, cond))

    def add_char(s: int, t: int, pred: object) -> None:
        char_edges[s].append((pred, t))

    def make_atom(pred: object) -> tuple[int, int]:
        s = new_state()
        t = new_state()
        add_char(s, t, pred)
        return s, t

    def combine_or(frags: list[tuple[int, int]]) -> tuple[int, int]:
        if len(frags) == 1:
            return frags[0]
        start = new_state()
        end = new_state()
        for s, t in frags:
            add_eps(start, s, C_NONE)
            add_eps(t, end, C_NONE)
        return start, end

    def apply_quantifier(frag: tuple[int, int], op: str) -> tuple[int, int]:
        s, t = frag
        ns = new_state()
        ne = new_state()

        if op == "?":
            add_eps(ns, s, C_NONE)
            add_eps(ns, ne, C_NONE)
            add_eps(t, ne, C_NONE)
            return ns, ne

        if op == "*":
            add_eps(ns, s, C_NONE)
            add_eps(ns, ne, C_NONE)
            add_eps(t, ns, C_NONE)
            return ns, ne

        if op == "+":
            add_eps(t, s, C_NONE)
            add_eps(t, ne, C_NONE)
            return s, ne

        raise ValueError

    def read_one(i: int) -> tuple[str, int]:
        if p[i] == "\\":
            if i + 1 >= pn:
                raise ValueError
            return p[i + 1], i + 2
        return p[i], i + 1

    def parse_class() -> object:
        idx = 0
        if p[idx] != "[":
            raise ValueError
        idx += 1

        negated = False
        if idx < pn and p[idx] == "^":
            negated = True
            idx += 1

        items: list[tuple[int, int]] = []

        while idx < pn:
            if p[idx] == "]":
                if not items:
                    raise ValueError
                idx += 1

                items.sort()
                merged: list[tuple[int, int]] = []
                lo, hi = items[0]
                for a, b in items[1:]:
                    if a <= hi + 1:
                        if b > hi:
                            hi = b
                    else:
                        merged.append((lo, hi))
                        lo, hi = a, b
                merged.append((lo, hi))

                return ("C", bool(negated), merged)

            c1, idx = read_one(idx)
            o1 = ord(c1)

            if idx < pn and p[idx] == "-":
                # If '-' is followed by ']', it is a literal hyphen.
                if not (idx + 1 < pn and p[idx + 1] == "]"):
                    idx += 1
                    c2, idx = read_one(idx)
                    o2 = ord(c2)
                    if o1 > o2:
                        raise ValueError
                    items.append((o1, o2))
                    continue

            items.append((o1, o1))

        raise ValueError

    idx = 0

    def parse_alt(stop: str) -> tuple[int, int]:
        nonlocal idx

        alts: list[tuple[int, int]] = []
        alts.append(parse_concat(stop))

        while idx < pn and p[idx] == "|":
            idx += 1
            alts.append(parse_concat(stop))

        return combine_or(alts)

    def parse_concat(stop: str) -> tuple[int, int]:
        nonlocal idx

        frags: list[tuple[int, int]] = []

        while idx < pn and p[idx] not in stop and p[idx] != "|":
            ch = p[idx]

            if ch == ")":
                raise ValueError

            if ch == "(":
                idx += 1
                frag = parse_alt(")")
                if idx >= pn or p[idx] != ")":
                    raise ValueError
                idx += 1
                quantifiable = True

            elif ch == "[":
                pred = parse_class()
                frag = make_atom(pred)
                quantifiable = True

            elif ch == ".":
                idx += 1
                frag = make_atom(DOT)
                quantifiable = True

            elif ch == "^":
                idx += 1
                s = new_state()
                t = new_state()
                add_eps(s, t, C_START)
                frag = (s, t)
                quantifiable = False

            elif ch == "$":
                idx += 1
                s = new_state()
                t = new_state()
                add_eps(s, t, C_END)
                frag = (s, t)
                quantifiable = False

            elif ch == "\\":
                if idx + 1 >= pn:
                    raise ValueError
                c = p[idx + 1]
                idx += 2
                frag = make_atom(ord(c))
                quantifiable = True

            elif ch in "*+?":
                raise ValueError

            else:
                c = ch
                idx += 1
                frag = make_atom(ord(c))
                quantifiable = True

            if quantifiable and idx < pn and p[idx] in "*+?":
                op = p[idx]
                idx += 1
                frag = apply_quantifier(frag, op)
                quantifiable = False
                if idx < pn and p[idx] in "*+?":
                    raise ValueError

            frags.append(frag)

        if not frags:
            s = new_state()
            return s, s

        start, end = frags[0]
        for s, t in frags[1:]:
            add_eps(end, s, C_NONE)
            end = t
        return start, end

    start_state, accept_state = parse_alt("")
    if idx != pn:
        raise ValueError

    def epsilon_closure(states: set[int], pos: int) -> set[int]:
        result = set(states)
        stack = list(result)

        while stack:
            s = stack.pop()
            for t, cond in eps_edges[s]:
                if cond == C_NONE:
                    ok = True
                elif cond == C_START:
                    ok = (pos == 0)
                elif cond == C_END:
                    ok = (pos == tn)
                else:
                    ok = False

                if ok and t not in result:
                    result.add(t)
                    stack.append(t)

        return result

    def match_pred(pred: object, code: int) -> bool:
        if pred == DOT:
            return True
        if type(pred) is int:
            return code == pred

        # pred == ("C", negated, ranges)
        negated = pred[1]
        ranges = pred[2]
        inside = False
        for lo, hi in ranges:
            if code < lo:
                break
            if code <= hi:
                inside = True
                break
        return inside ^ negated

    active: set[int] = set()

    for pos in range(tn + 1):
        active.add(start_state)
        active = epsilon_closure(active, pos)

        if accept_state in active:
            return True

        if pos == tn:
            break

        code = text_codes[pos]
        nxt: set[int] = set()
        for s in active:
            for pred, t in char_edges[s]:
                if match_pred(pred, code):
                    nxt.add(t)
        active = nxt

    return False
